<?php
/** Plugin Name: TEMP PS S1728mm petshop-fbt v1.7.1 (V2 blokas po "Į krepšelį"). Fazes: 1 dry, 2 deploy, 3 patikra, 9 atstatyti (i v1.7.0 + tvarka atgal) */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1728mm'])) return; $f=(string)$_GET['ps_s1728mm']; $r=['v'=>'S1728mm','faze'=>$f,'laikas'=>current_time('mysql')]; @set_time_limit(170);
  $fp=WP_PLUGIN_DIR.'/petshop-fbt/petshop-fbt.php'; $arch=dirname(untrailingslashit(ABSPATH)).'/ps-archyvas'; $bak=$arch.'/petshop-fbt.php.bak_s1728b';
  $SENAS='24c78e5d1d12526197b86802545e93e5'; $NAUJAS='35370264060cb7eab7f9f16928b9e491';
  $B64='';
  $tok=function($code){ try{ token_get_all($code,TOKEN_PARSE); return 'ok'; }catch(Throwable $e){ return 'KLAIDA '.$e->getMessage(); } };
  $hb=function(){ $o=[]; $x=wp_remote_get(home_url('/?ps_hb='.time()),['timeout'=>30,'sslverify'=>false]); $o['front']=is_wp_error($x)?$x->get_error_message():wp_remote_retrieve_response_code($x); $y=wp_remote_get(admin_url('admin-ajax.php?action=heartbeat&t='.time()),['timeout'=>30,'sslverify'=>false]); $o['admin_ajax']=is_wp_error($y)?$y->get_error_message():wp_remote_retrieve_response_code($y); return $o; };
  try{
    $new=gzuncompress(base64_decode($B64));
    if($f==='1'){ $r['gyvas_md5']=md5_file($fp); $r['gyvas_sutampa']=($r['gyvas_md5']===$SENAS); $r['naujas_ok']=(md5($new)===$NAUJAS); $r['lint']=$tok($new); $r['bak_yra']=is_file($bak); $r['tvarka_isjungta']=get_option('ps_prekes_tvarka_isjungta'); }
    if($f==='2'){
      $cur=md5_file($fp); if($cur!==$SENAS && $cur!==$NAUJAS) throw new Exception('gyvas failas pasikeitė: '.$cur);
      if(md5($new)!==$NAUJAS || $tok($new)!=='ok') throw new Exception('naujas turinys blogas');
      if(!is_file($bak)) copy($fp,$bak); $r['bak_md5']=md5_file($bak);
      if(get_option('ps_s1728_tvarka_bak')===false) update_option('ps_s1728_tvarka_bak',['buvo'=>get_option('ps_prekes_tvarka_isjungta','__nera__')],false);
      file_put_contents($fp,$new); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['md5']=md5_file($fp);
      update_option('ps_prekes_tvarka_isjungta','1',false); $r['tvarka']='išjungta (FBT po „Į krepšelį", virš skaičiuoklės)';
      sleep(2); $r['hb']=$hb();
      if($r['hb']['front']!==200 || $r['hb']['admin_ajax']===500){ copy($bak,$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); delete_option('ps_prekes_tvarka_isjungta'); $r['ROLLBACK']=true; $r['hb_po']=$hb(); }
      elseif(function_exists('wp_cache_clear_cache')){ wp_cache_clear_cache(); $r['kesas']='išvalytas'; }
    }
    if($f==='3'){
      $r['md5']=md5_file($fp); $r['versija']=get_file_data($fp,['v'=>'Version'])['v']; $r['hb']=$hb();
      foreach([17978,18587,19092,26391] as $pid){ $u=add_query_arg('ps_hb',time().$pid,get_permalink($pid)); $x=wp_remote_get($u,['timeout'=>40,'sslverify'=>false,'cookies'=>['ps_js'=>'1'],'user-agent'=>'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) Mobile/15E148']);
        $b=is_wp_error($x)?'':wp_remote_retrieve_body($x); $pf=strpos($b,'<form class="cart"'); $pe=$pf!==false?strpos($b,'</form>',$pf):false; $pb=strpos($b,'<div class="petshop-fbt"'); $pc=strpos($b,'id="ps-calc"');
        $o=['kodas'=>is_wp_error($x)?$x->get_error_message():wp_remote_retrieve_response_code($x),'forma_iki'=>$pe,'fbt'=>$pb,'calc'=>$pc,'fbt_po_forma'=>($pb!==false&&$pe!==false&&$pb>$pe),'fbt_virs_calc'=>($pc===false||($pb!==false&&$pb<$pc)),'eiluciu'=>substr_count($b,'class="petshop-fbt__row"'),'mygtukas'=>preg_match('~petshop-fbt__add">([^<]*)<~u',$b,$m)?$m[1]:null,'tarp'=>$pe!==false&&$pb!==false?mb_substr(trim(preg_replace('/\s+/',' ',strip_tags(substr($b,$pe,$pb-$pe)))),0,200):''];
        $r['psl'][$pid]=$o; }
      $log=dirname(untrailingslashit(ABSPATH)).'/logs/php_error.log'; if(is_file($log)){ $t=@file($log); $t=$t?array_slice($t,-300):[]; $r['php_log_fbt']=array_values(array_slice(array_filter($t,function($l){ return stripos($l,'petshop-fbt')!==false && strpos($l,date('d-M-Y'))!==false; }),-8)); }
    }
    if($f==='9'){
      if(!is_file($bak)) throw new Exception('bak nėra'); copy($bak,$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); $r['md5']=md5_file($fp);
      $b=get_option('ps_s1728_tvarka_bak'); if(is_array($b) && $b['buvo']==='__nera__') delete_option('ps_prekes_tvarka_isjungta'); elseif(is_array($b)) update_option('ps_prekes_tvarka_isjungta',$b['buvo'],false);
      if(function_exists('wp_cache_clear_cache')) wp_cache_clear_cache(); sleep(1); $r['hb']=$hb();
    }
  }catch(Throwable $e){ $r['KLAIDA']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE); exit;
}, 1);
